    /// `scan(init, body, length)`. `body`'s inputs are, in creation order,
    /// the carry, each broadcast, then each per-step slice of `xs`; its one
    /// output is the next carry. The body graph is **consumed**.
    /// `trajectory` returns every carry stacked (`[length, …init]`).
    @discardableResult
    func scan(_ `init`: Node, body: Graph, length: UInt32, xs: [Node] = [], bcasts: [Node] = [], checkpoints: UInt32 = 0, trajectory: Bool = false) throws -> Node {
        let xsIds = xs.map(\.id)
        let bcastsIds = bcasts.map(\.id)
        var ret: UInt32 = 0
        try check(rlx_graph_scan(handle, `init`.id, body.handle, length, xsIds, xsIds.count, bcastsIds, bcastsIds.count, checkpoints, trajectory, &ret))
        return Node(id: ret)
    }

    /// A sub-graph with optional hand-written AD rules (`custom_vjp` /
    /// `custom_jvp`). Every body graph passed in is consumed.
    @discardableResult
    func customFn(_ inputs: [Node], fwdBody: Graph, vjpBody: Graph? = nil, jvpBody: Graph? = nil) throws -> Node {
        let inputsIds = inputs.map(\.id)
        var ret: UInt32 = 0
        try check(rlx_graph_custom_fn(handle, inputsIds, inputsIds.count, fwdBody.handle, vjpBody?.handle, jvpBody?.handle, &ret))
        return Node(id: ret)
    }

    /// One node per output of `fwd_body`, which is consumed.
    @discardableResult
    func customFnMulti(_ inputs: [Node], fwdBody: Graph) throws -> [Node] {
        let inputsIds = inputs.map(\.id)
        var ret = RlxU32s(ptr: nil, len: 0)
        try check(rlx_graph_custom_fn_multi(handle, inputsIds, inputsIds.count, fwdBody.handle, &ret))
        return takeU32s(ret).map { Node(id: $0) }
    }

    /// An op registered through `rlx_ir::register_op`. `attrs` is its
    /// serialized attribute bytes; `out_shape` declares a packed output.
    @discardableResult
    func customOp(_ name: String, inputs: [Node], attrs: [UInt8] = [], outShape: [Int]? = nil, dtype: String = "f32") throws -> Node {
        let inputsIds = inputs.map(\.id)
        var ret: UInt32 = 0
        try withOptionalArray(outShape) { outShapeP, outShapeN in
            try check(rlx_graph_custom_op(handle, name, inputsIds, inputsIds.count, attrs, attrs.count, outShapeP, outShapeN, dtype, &ret))
        }
        return Node(id: ret)
    }

